// --- Local Storage ---
// Needs to be stringified because storage only holds strings
const userPrefs = { theme: 'dark', fontSize: 16 };
localStorage.setItem('prefs', JSON.stringify(userPrefs));

// Retrieve and parse
const savedPrefs = JSON.parse(localStorage.getItem('prefs'));
console.log(savedPrefs.theme); // 'dark'


// --- Session Storage ---
// Disappears when tab is closed
sessionStorage.setItem('currentStep', '3');


// --- Cookies ---
// Basic JS Cookie (Bad for security)
document.cookie = "username=Alice; expires=Thu, 18 Dec 2025 12:00:00 UTC; path=/";

console.log("Web Storage is synchronous and blocking, so don't store huge amounts of data!");
